    # ===== 形態素分割改善のための連語エントリ =====
    # 漢数字だけの表層は単体で出ると誤読の原因になるため 10000 で死にエントリ化しているが、実際に使われる複合語だけは連語エントリで救う（「八百万」を「ハッピャクマン」、「五十六」を「ゴジューロク」と読む実害を確認済み）
    "八百万の神,1345,1345,3000,名詞,一般,*,*,*,*,八百万の:神,ヤオヨロズノ:カミ,ヤオヨロズノ:カミ,3/6:1/2,C2",
    # 「〜月」の連濁は生産的だが、辞書へ列挙できる頻出語だけ連語で救う
    # 単体の「月」（「ヅキ」）を安くすると「三日月」や「○月○日」まで巻き込むため、複合語側で固定する
    # 発音欄は「ヂ」「ヅ」を「ジ」「ズ」で表記する規則に従い、読み欄だけ仮名遣いどおり「ヅ」を残す
    "誕生月,1345,1345,4500,名詞,一般,*,*,*,*,誕生月,タンジョウヅキ,タンジョーズキ,3/6,C1",
