    "奇数月,1345,1345,4500,名詞,一般,*,*,*,*,奇数月,キスウヅキ,キスーズキ,2/5,C1",
    "偶数月,1345,1345,4500,名詞,一般,*,*,*,*,偶数月,グウスウヅキ,グースーズキ,3/6,C1",
    # 「前々」や「先々」に時間や序列の名詞が続く複合語は、コスト 744 の「前々」（「マエマエ」）で分割する解析に負け、どれも正しく読めていなかった
    # 「前々」が prefix に付く複合語例として前々回・前々条・前々年度・前々夜・前々月・前々週がある
    # 個別エントリを持つのは「前々回」だけなので、実在を確認できた語を連語で固定する
    "前々月,1345,1345,4500,名詞,一般,*,*,*,*,前々月,ゼンゼンゲツ,ゼンゼンゲツ,3/6,C1",
