# 和集合 (e097e91 + 7910eb7)
NAIST_REMOVAL_KEYS: frozenset[tuple[str, str, str, str]] = (
    HETERONYM_NAIST_MIGRATION_REMOVAL_KEYS | CONTEXT_ID_SUPERSEDED_REMOVAL_KEYS
)


def _normalize_key_field(value: str) -> str:
    """辞書照合用にコロン区切りアクセントを正規化する。"""

    return value.replace(":", "")


def _entry_identity_key(row: list[str]) -> tuple[str, str, str, str]:
    """CSV 行の識別キー (surface, context_id, orig, read) を返す。"""

    # OpenJTalk デフォルト辞書では left_id と right_id が一致するため、left_id を文脈 ID として使う
    return (
        row[0],
        row[1],
        _normalize_key_field(row[10]),
        _normalize_key_field(row[11]),
    )


def _surface_context_read_key(row: list[str]) -> tuple[str, str, str]:
    """コスト調整用の識別キー (surface, context_id, read) を返す。"""

    return (row[0], row[1], _normalize_key_field(row[11]))


def _is_kanji_numeric_name_row(row: list[str]) -> bool:
    """surface が漢数字だけの人名（姓・名）エントリかどうかを判定する。"""

    return (
        row[1] in KANJI_NUMERIC_NAME_CONTEXT_IDS
        and KANJI_NUMERIC_NAME_SURFACE_RE.fullmatch(row[0]) is not None
    )


def _limit_katakana_common_noun_cost(rows: list[list[str]]) -> int:
    """未知語候補と競合するカタカナ一般名詞のコストを下げる。"""

    cost_adjustment_count = 0
    for row in rows:
        # KATAKANA を未知語候補としても起動するため、既知の一般名詞は未知語より優先する
        if (
            row[4] == "名詞"
            and row[5] == "一般"
            and KATAKANA_SURFACE_RE.fullmatch(row[0]) is not None
            and int(row[3]) > KATAKANA_COMMON_NOUN_COST_MAX
        ):
            row[3] = str(KATAKANA_COMMON_NOUN_COST_MAX)
            cost_adjustment_count += 1
    return cost_adjustment_count


def modify_dictionary() -> None:
    """辞書 CSV を読み込み、修正して上書き保存する。"""

    with open(DICT_PATH, encoding="utf-8", newline="") as f:
        rows = list(csv.reader(f))

    print(f"Read {len(rows)} entries from {DICT_PATH.name}")

    # --- 凍結した削除台帳 (e097e91 / 7910eb7) に基づく naist-jdic.csv からの行削除 ---
    before_count = len(rows)
    rows = [row for row in rows if _entry_identity_key(row) not in NAIST_REMOVAL_KEYS]
    remove_count = before_count - len(rows)
    print(f"Removed {remove_count} entries from frozen naist-jdic.csv removal ledgers")

    # 既存の (surface, context_id, read) を収集（重複追加防止用）
    # (surface, read) だけでは品詞の違う同音エントリ（「千切れ」の動詞未然形・連用形・名詞など）を区別できないため、文脈 ID を含めて識別する
    # 複合語アクセントのコロン（例: 「ジシン:フセツ」）は除去して正規化する
    existing_keys: set[tuple[str, str, str]] = set()
    for row in rows:
        existing_keys.add(_surface_context_read_key(row))

    # --- 読み修正 ---
    fix_count = 0
    for i, row in enumerate(rows):
        key = (row[0], row[11])
        if key in READING_FIXES:
            fixes = READING_FIXES[key]
            if "read" in fixes:
                rows[i][11] = fixes["read"]
            if "pron" in fixes:
                rows[i][12] = fixes["pron"]
            if "acc" in fixes:
                rows[i][13] = fixes["acc"]
            fix_count += 1
            # 読み修正後のキーを更新
            existing_keys.discard((row[0], row[1], _normalize_key_field(key[1])))
            existing_keys.add(_surface_context_read_key(rows[i]))
    print(f"Applied {fix_count} reading fixes")

    # --- 品詞・文脈 ID 等のフィールド修正 ---
    field_fix_count = 0
    for i, row in enumerate(rows):
        key = _entry_identity_key(row)
        if key not in FIELD_FIXES:
            continue
        updates = FIELD_FIXES[key]
        changed = False
        for col_idx, new_value in updates.items():
            if rows[i][col_idx] != new_value:
                rows[i][col_idx] = new_value
                changed = True
        if changed:
            field_fix_count += 1
    print(f"Applied {field_fix_count} field fixes from FIELD_FIXES ledger")

    # --- 活用形のコスト調整（プレフィックスマッチ） ---
    # 各行に対して最も絞り込んだ（prefix が最長の）ルールだけを適用する
    # COST_ADJUSTMENTS に完全一致する行はそちらを優先するためスキップする
    cost_count = 0

    # 各行に対する最も絞り込んだ CONJ ルールを決定
    # キー: 行インデックス、値: (specificity, new_cost)
    # specificity = surface_prefix の長さ + read_prefix の長さ（長いほど絞り込んだルール）
    conj_best: dict[int, tuple[int, int]] = {}
    for surface_prefix, orig_prefix, read_prefix, new_cost, _ in CONJUGATION_COST_ADJUSTMENTS:
        for i, row in enumerate(rows):
            if (
                row[0].startswith(surface_prefix)
                and row[10].startswith(orig_prefix)
                and row[11].startswith(read_prefix)
            ):
                # 既存の広い調整と文脈 ID 指定の調整を優先し、活用形の候補順位を保つ
                if (row[0], row[11]) in COST_ADJUSTMENTS or (
                    _surface_context_read_key(row) in CONTEXT_EXACT_COST_ADJUSTMENTS
                ):
                    continue
                specificity = len(surface_prefix) + len(read_prefix)
                prev = conj_best.get(i)
                if prev is None or specificity > prev[0]:
                    conj_best[i] = (specificity, new_cost)

    for i, (_, new_cost) in conj_best.items():
        if rows[i][3] != str(new_cost):
            rows[i][3] = str(new_cost)
            cost_count += 1

    # --- 「柄」（接尾辞の「ガラ」も下げる） ---
    # COST_ADJUSTMENTS の ("柄", "ガラ") は名詞,一般 (文脈ID: 1345) にのみ適用される
    # 接尾辞 (pos="接尾") は文脈 ID が異なるため別途ここで同じコストに揃える
    for i, row in enumerate(rows):
        if row[0] == "柄" and row[11] == "ガラ" and row[5] == "接尾":
            if row[3] != "4000":
                row[3] = "4000"
                cost_count += 1

    # --- 文脈 ID 指定のコスト調整 ---
    # 同じ surface/read でも品詞や活用形で文脈 ID が異なるため、指定行だけを終点値へ揃える
    for i, row in enumerate(rows):
        key = _surface_context_read_key(row)
        if key not in CONTEXT_EXACT_COST_ADJUSTMENTS:
            continue
        new_cost = str(CONTEXT_EXACT_COST_ADJUSTMENTS[key])
        if row[3] != new_cost:
            row[3] = new_cost
            cost_count += 1

    # --- コスト調整 (surface, read): 完全一致のルールなのでプレフィックスルールの後に適用 ---
    # NEW_ENTRIES が管理するエントリは NEW_ENTRIES 側でコストが確定するため、ここではスキップする
    # (surface, read) のみでマッチする COST_ADJUSTMENTS が、異なる文脈 ID の NEW_ENTRIES エントリまで巻き込んで上書きするのを防ぐ
    new_entries_keys: set[tuple[str, str, str]] = set()
    for entry in NEW_ENTRIES:
        parsed = next(iter(csv.reader([entry])))
        new_entries_keys.add(_surface_context_read_key(parsed))
    for i, row in enumerate(rows):
        key = (row[0], row[11])
        if key in COST_ADJUSTMENTS:
            # NEW_ENTRIES で管理されているエントリはスキップ
            ne_key = _surface_context_read_key(row)
            if ne_key in new_entries_keys:
                continue
            # 文脈 ID 指定の調整行は、広い既存調整より優先して候補順位を確定する
            if ne_key in CONTEXT_EXACT_COST_ADJUSTMENTS:
                continue
            new_cost = str(COST_ADJUSTMENTS[key])
            if row[3] != new_cost:
                row[3] = new_cost
                cost_count += 1

    # --- 文脈 ID 指定付きのコスト調整 ---
    for surface, context_id, read, old_cost_max, new_cost in SPECIAL_COST_ADJUSTMENTS:
        for i, row in enumerate(rows):
            if (
                row[0] == surface
                and row[1] == context_id
                and row[11] == read
                and int(row[3]) <= old_cost_max
            ):
                if row[3] != str(new_cost):
                    row[3] = str(new_cost)
                    cost_count += 1

    # --- surface が漢数字だけの人名（姓・名）を死にエントリ化 ---
    for i, row in enumerate(rows):
        if not _is_kanji_numeric_name_row(row):
            continue
        ne_key = _surface_context_read_key(row)
        if ne_key in new_entries_keys:
            continue
        if int(row[3]) < KANJI_NUMERIC_NAME_COST:
            row[3] = str(KANJI_NUMERIC_NAME_COST)
            cost_count += 1

    cost_count += _limit_katakana_common_noun_cost(rows)

    print(f"Applied {cost_count} cost adjustments")

    # --- 新規エントリ追加・既存エントリ上書き ---
    # キーが一致するエントリが既に CSV に存在する場合、NEW_ENTRIES の内容で丸ごと上書きする
    # これにより、アクセント等のフィールドをスクリプト側で変更しても再実行時に反映される
    # 複合語アクセント対応: read フィールドにコロン区切り（例: 「ジシン:フセツ」）が含まれる場合、
    # コロンを除去した値（「ジシンフセツ」）でも照合する
    # これにより、NEW_ENTRIES 側でコロンの有無を変更しても、既存エントリと正しく照合される
    add_count = 0
    update_count = 0
    # 既存エントリの行インデックスを逆引きするマップ（識別キー → 行インデックス配列）
    # 同一 surface / read でも orig やアクセントが異なる既存行があるため、
    # 1 対 1 と仮定せずに候補配列で保持し、一意に決まらない場合は上書きせずに append する
    existing_identity_to_indices: dict[tuple[str, str, str, str], list[int]] = {}
    for i, row in enumerate(rows):
        identity_key = _entry_identity_key(row)
        existing_identity_to_indices.setdefault(identity_key, []).append(i)
    for entry in NEW_ENTRIES:
        parsed = next(iter(csv.reader([entry])))
        identity_key = _entry_identity_key(parsed)
        candidate_indices = existing_identity_to_indices.get(identity_key, [])
        if len(candidate_indices) == 1:
            # 既存エントリを上書き（内容が異なる場合のみカウント）
            idx = candidate_indices[0]
            if rows[idx] != parsed:
                rows[idx] = parsed
                update_count += 1
        elif len(candidate_indices) > 1:
            exact_match_idx = next((idx for idx in candidate_indices if rows[idx] == parsed), None)
            if exact_match_idx is None:
                rows.append(parsed)
                # identity_key は candidate_indices > 1 なので必ず存在する
                existing_identity_to_indices[identity_key].append(len(rows) - 1)
                add_count += 1
        else:
            rows.append(parsed)
            existing_identity_to_indices.setdefault(identity_key, []).append(len(rows) - 1)
            add_count += 1

    print(f"Added {add_count} new entries, updated {update_count} existing entries")

    # --- surface でソートして書き込み（末尾の改行を除去） ---
    rows.sort(key=lambda row: row[0])
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerows(rows)
    content = buf.getvalue().rstrip("\n")

    with open(DICT_PATH, "w", encoding="utf-8", newline="") as f:
        f.write(content)

    print(f"Wrote {len(rows)} entries to {DICT_PATH.name}")

    with open(UNIDIC_CSJ_PATH, encoding="utf-8", newline="") as f:
        unidic_rows = list(csv.reader(f))
    unidic_katakana_cost_adjustment_count = _limit_katakana_common_noun_cost(unidic_rows)
    unidic_death_ni_cost_adjustment_count = 0
    # 同じ読みを持つ動詞活用形へ波及させず、表記と文脈 ID が一致する候補だけを優先する
    for row in unidic_rows:
        key = _surface_context_read_key(row)
        if key not in UNIDIC_DEATH_NI_COST_ADJUSTMENTS:
            continue
        new_cost = str(UNIDIC_DEATH_NI_COST_ADJUSTMENTS[key])
        if row[3] != new_cost:
            row[3] = new_cost
            unidic_death_ni_cost_adjustment_count += 1
    unidic_rare_syllable_fix_count = 0
    # 同じ表層の別候補を避け、稀音節が落ちた辞書行だけへ読みと発音を戻す
    for row in unidic_rows:
        key = (row[0], row[1])
        if key not in UNIDIC_RARE_SYLLABLE_READING_FIXES:
            continue
        read, pron, acc = UNIDIC_RARE_SYLLABLE_READING_FIXES[key]
        if row[11] != read or row[12] != pron or row[13] != acc:
            row[11] = read
            row[12] = pron
            row[13] = acc
            unidic_rare_syllable_fix_count += 1
    unidic_compound_cost_adjustment_count = 0
    # 同じ表層の異なる辞書候補へ波及させず、表に載せた複合語の行だけを優先する
    for row in unidic_rows:
        key = _surface_context_read_key(row)
        if key not in UNIDIC_COMPOUND_COST_ADJUSTMENTS:
            continue
        new_cost = str(UNIDIC_COMPOUND_COST_ADJUSTMENTS[key])
        if row[3] != new_cost:
            row[3] = new_cost
            unidic_compound_cost_adjustment_count += 1
    unidic_field_fix_count = 0
    for row in unidic_rows:
        key = _surface_context_read_key(row)
        if key not in UNIDIC_FIELD_FIXES:
            continue
        updates = UNIDIC_FIELD_FIXES[key]
        if any(row[col_idx] != new_value for col_idx, new_value in updates.items()):
            for col_idx, new_value in updates.items():
                row[col_idx] = new_value
            unidic_field_fix_count += 1
    unidic_rows.sort(key=lambda row: row[0])
    unidic_buffer = io.StringIO()
    csv.writer(unidic_buffer, lineterminator="\n").writerows(unidic_rows)

    with open(UNIDIC_CSJ_PATH, "w", encoding="utf-8", newline="") as f:
        f.write(unidic_buffer.getvalue().rstrip("\n"))

    print(
        f"Applied {unidic_katakana_cost_adjustment_count} KATAKANA common noun cost adjustments "
        f"to {UNIDIC_CSJ_PATH.name}"
    )
    print(
        f"Applied {unidic_death_ni_cost_adjustment_count} death-ni cost adjustments "
        f"to {UNIDIC_CSJ_PATH.name}"
    )
    print(
        f"Applied {unidic_rare_syllable_fix_count} rare syllable reading fixes to {UNIDIC_CSJ_PATH.name}"
    )
    print(
        "Applied "
        f"{unidic_compound_cost_adjustment_count} compound cost adjustments "
        f"to {UNIDIC_CSJ_PATH.name}"
    )
    print(f"Applied {unidic_field_fix_count} field fixes to {UNIDIC_CSJ_PATH.name}")


if __name__ == "__main__":
    modify_dictionary()
